An overgrown Controller, with genuine business logic creeping in (calculating a discount, checking inventory, and recording the order, all inline):

// Controller doing too much (the problem this lesson solves)
export async function checkout(req: Request, res: Response, next: NextFunction) {
  try {
    const { items, couponCode } = req.body;
    let total = items.reduce((sum: number, item: any) => sum + item.price * item.quantity, 0);
    if (couponCode === 'SAVE10') total *= 0.9; // business logic, inline
    for (const item of items) {
      const stock = await inventoryCollection.findOne({ id: item.id });
      if (!stock || stock.quantity < item.quantity) {
        return res.status(400).json({ success: false, error: `Insufficient stock for ${item.id}` });
      }
    }
    const order = await ordersCollection.insertOne({ items, total, createdAt: new Date() });
    res.status(201).json({ success: true, data: order });
  } catch (err) {
    next(err);
  }
}

Extracted into a Service, with the Controller reduced to genuine orchestration:

// services/orderService.ts
export async function processCheckout(items: CartItem[], couponCode?: string) {
  for (const item of items) {
    const stock = await inventoryCollection.findOne({ id: item.id });
    if (!stock || stock.quantity < item.quantity) {
      throw new InsufficientStockError(item.id);
    }
  }
  let total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  if (couponCode === 'SAVE10') total *= 0.9;
  return ordersCollection.insertOne({ items, total, createdAt: new Date() });
}

// controllers/orderController.ts - now genuinely thin
export async function checkout(req: Request, res: Response, next: NextFunction) {
  try {
    const order = await processCheckout(req.body.items, req.body.couponCode);
    res.status(201).json({ success: true, data: order });
  } catch (err) {
    if (err instanceof InsufficientStockError) {
      return res.status(400).json({ success: false, error: err.message });
    }
    next(err);
  }
}

