export class InsufficientStockError extends Error {
  constructor(itemId: string) {
    super(`Insufficient stock for item ${itemId}`);
    this.name = 'InsufficientStockError';
  }
}

export async function processCheckout(items: CartItem[], couponCode?: string) {
  for (const item of items) {
    const stock = await inventoryCollection.findOne({ id: item.id });
    if (!stock || stock.quantity < item.quantity) {
      throw new InsufficientStockError(item.id);
    }
  }
  let total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  if (couponCode === 'SAVE10') total *= 0.9;
  return ordersCollection.insertOne({ items, total, createdAt: new Date() });
}

// controllers/orderController.ts - the normal, HTTP-triggered checkout
export async function checkout(req: Request, res: Response, next: NextFunction) {
  try {
    const order = await processCheckout(req.body.items, req.body.couponCode);
    res.status(201).json({ success: true, data: order });
  } catch (err) {
    if (err instanceof InsufficientStockError) {
      return res.status(400).json({ success: false, error: err.message });
    }
    next(err);
  }
}

// scripts/processQueuedOrders.ts - a completely separate, non-HTTP
// entry point (perhaps a scheduled background job) reusing the EXACT
// same business logic with zero duplication
async function processQueuedOrders() {
  const queuedOrders = await getQueuedOrdersFromSomewhere();
  for (const queued of queuedOrders) {
    try {
      await processCheckout(queued.items, queued.couponCode);
    } catch (err) {
      console.error('Failed to process queued order:', err);
    }
  }
}

