The Repository interface (what any implementation must provide):

interface TaskRepository {
  findAll(): Promise<Task[]>;
  findById(id: string): Promise<Task | null>;
  create(title: string): Promise<Task>;
  delete(id: string): Promise<boolean>;
}

A MongoDB implementation, directly extending Module 8's MongoDB CRUD patterns:

class MongoTaskRepository implements TaskRepository {
  async findAll(): Promise<Task[]> {
    return tasksCollection.find().toArray();
  }
  async findById(id: string): Promise<Task | null> {
    return tasksCollection.findOne({ _id: new ObjectId(id) });
  }
  async create(title: string): Promise<Task> {
    const result = await tasksCollection.insertOne({ title, completed: false });
    return { id: result.insertedId, title, completed: false };
  }
  async delete(id: string): Promise<boolean> {
    const result = await tasksCollection.deleteOne({ _id: new ObjectId(id) });
    return result.deletedCount > 0;
  }
}

A Service depending ONLY on the interface, never the concrete class:

class TaskService {
  constructor(private taskRepository: TaskRepository) {}

  async getAllTasks(): Promise<Task[]> {
    return this.taskRepository.findAll();
  }
}

