// A second, completely different implementation of the SAME interface,
// directly extending Module 8 lesson 9's PostgreSQL patterns
class PostgresTaskRepository implements TaskRepository {
  async findAll(): Promise<Task[]> {
    const result = await pool.query('SELECT * FROM tasks');
    return result.rows;
  }
  async findById(id: string): Promise<Task | null> {
    const result = await pool.query('SELECT * FROM tasks WHERE id = $1', [id]);
    return result.rows[0] || null;
  }
  async create(title: string): Promise<Task> {
    const result = await pool.query(
      'INSERT INTO tasks (title, completed) VALUES ($1, false) RETURNING *',
      [title]
    );
    return result.rows[0];
  }
  async delete(id: string): Promise<boolean> {
    const result = await pool.query('DELETE FROM tasks WHERE id = $1', [id]);
    return result.rowCount > 0;
  }
}

// At application startup - the ONLY place that decides which database is used
const taskRepository: TaskRepository =
  process.env.DATABASE_TYPE === 'postgres'
    ? new PostgresTaskRepository()
    : new MongoTaskRepository();

const taskService = new TaskService(taskRepository);

// EVERYTHING else - TaskService's own code, every Controller using it,
// every route - remains completely, identically unchanged regardless
// of which Repository implementation was actually selected here

