interface Comment {
  id: string;
  postId: string;
  text: string;
}

interface CommentRepository {
  findByPostId(postId: string): Promise<Comment[]>;
  create(postId: string, text: string): Promise<Comment>;
}

class MongoCommentRepository implements CommentRepository {
  async findByPostId(postId: string): Promise<Comment[]> {
    return commentsCollection.find({ postId }).toArray();
  }
  async create(postId: string, text: string): Promise<Comment> {
    const result = await commentsCollection.insertOne({ postId, text });
    return { id: result.insertedId.toString(), postId, text };
  }
}

class FakeCommentRepository implements CommentRepository {
  private comments: Comment[] = [];
  async findByPostId(postId: string): Promise<Comment[]> {
    return this.comments.filter((c) => c.postId === postId);
  }
  async create(postId: string, text: string): Promise<Comment> {
    const comment = { id: String(Date.now()), postId, text };
    this.comments.push(comment);
    return comment;
  }
}

class CommentService {
  constructor(private commentRepository: CommentRepository) {}

  async getCommentsForPost(postId: string): Promise<Comment[]> {
    return this.commentRepository.findByPostId(postId);
  }
}

