import { z } from 'zod';
import sanitizeHtml from 'sanitize-html';

const createCommentSchema = z.object({
  postId: z.string(),
  text: z.string().min(1).max(1000)
});

class ValidationError extends Error {}

export async function createComment(req: Request, res: Response, next: NextFunction) {
  try {
    // STEP 1: VALIDATION - does this input meet the rules at all?
    const result = createCommentSchema.safeParse(req.body);
    if (!result.success) {
      return res.status(400).json({
        success: false,
        error: result.error.issues.map((i) => i.message).join(', ')
      });
    }

    // STEP 2: SANITISATION - even though text passed validation
    // (it's a non-empty string under 1000 characters), it could
    // still contain dangerous HTML that needs to be stripped before
    // ever being stored or eventually displayed to another user
    const sanitizedText = sanitizeHtml(result.data.text, {
      allowedTags: [],
      allowedAttributes: {}
    });

    const comment = await commentService.create(result.data.postId, sanitizedText);
    res.status(201).json({ success: true, data: comment });
  } catch (err) {
    next(err);
  }
}

