Different rate limiters for different tiers of route sensitivity, directly extending Module 9, lesson 7's express-rate-limit usage:

import rateLimit from 'express-rate-limit';

// Generous limit for public, read-only, low-cost routes
const publicReadLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 300 // 300 requests per 15 minutes
});

// Moderate limit for authenticated, write-heavy routes
const writeLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 50
});

// Strict limit for genuinely sensitive routes (Module 9 lesson 7's
// original login example, now one tier among several)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5
});

app.get('/api/products', publicReadLimiter, getProducts);
app.post('/api/orders', writeLimiter, requireAuth, createOrder);
app.post('/api/login', authLimiter, login);
app.post('/api/password-reset', authLimiter, requestPasswordReset);

