import rateLimit from 'express-rate-limit';

// Public routes - limit by IP, since there's no authenticated user yet
const publicLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 300,
  standardHeaders: true
});

// Authenticated routes - limit by the actual user's ID, not just IP,
// directly using Module 9's requireAuth middleware's req.userId
const authenticatedLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  keyGenerator: (req) => req.userId || req.ip, // prefer the real user
                                                  // ID; fall back to IP
                                                  // only if somehow unset
  standardHeaders: true
});

// Genuinely sensitive routes - strict limit, by IP (since a login
// attempt's whole point is that the user isn't authenticated yet)
const sensitiveLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  standardHeaders: true
});

app.get('/api/products', publicLimiter, getProducts);
app.use('/api/dashboard', requireAuth, authenticatedLimiter); // applied
  // to an entire router/section, not just one individual route
app.post('/api/login', sensitiveLimiter, login);

